SELECT n.id, n.msg_id, m.msg_template_id, m.title, m.content, m.url, m.source_type, m.source_id, m.priority, m.owner_name, n.has_read, n.notice_time, n.read_time, m.send_time FROM sys_msg_notice n INNER JOIN sys_msg m ON n.msg_id = m.id WHERE n.receiver_id = #{receiverId} AND m.deleted = 0
AND m.msg_template_id = #{msgTemplateId}
AND n.has_read = #{hasRead}
AND (m.title LIKE CONCAT('%', #{keyword}, '%') OR m.content LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY n.has_read asc, m.send_time desc

SELECT COUNT(*)
FROM sys_msg_notice n
INNER JOIN sys_msg m ON n.msg_id = m.id
WHERE n.receiver_id = #{receiverId}
AND m.deleted = 0

    AND m.msg_template_id = #{msgTemplateId}


    AND n.has_read = #{hasRead}


    AND (m.title LIKE CONCAT('%', #{keyword}, '%')
        OR m.content LIKE CONCAT('%', #{keyword}, '%'))
